package com.clavis.reader;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
final class FeedTabChecks {
 static View described(View root,String label){if(label.contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){View found=described(((ViewGroup)root).getChildAt(n),label);if(found!=null)return found;}return null;}
 static TextView text(View root,String label){if(root instanceof TextView&&((TextView)root).getText().toString().equals(label))return (TextView)root;if(root instanceof ViewGroup)for(int n=0;n<((ViewGroup)root).getChildCount();n++){TextView found=text(((ViewGroup)root).getChildAt(n),label);if(found!=null)return found;}return null;}
 static void refreshReturns(Instrumentation test,MainActivity a,boolean sources)throws Exception{final View[] previous={null};FeedStore.Feed fixture=new FeedStore.Feed();fixture.kind="News";fixture.url="https://refresh-check.invalid/feed-"+System.nanoTime();fixture.title="Refresh verification";FeedStore.put(a,fixture);try{test.runOnMainSync(()->{FeedScreens.show(a,"News",sources);previous[0]=a.mainFrame;FeedScreens.refresh(a,"News",new ArrayList<>(Collections.singletonList(fixture)),sources);});long until=android.os.SystemClock.uptimeMillis()+30000;boolean[] complete={false};while(!complete[0]&&android.os.SystemClock.uptimeMillis()<until){test.runOnMainSync(()->complete[0]=a.mainFrame!=previous[0]);if(!complete[0])android.os.SystemClock.sleep(100);}FeedPostChecks.check(complete[0],"Refresh completes even when a source is unavailable");test.runOnMainSync(()->FeedPostChecks.check(text(a.mainFrame,sources?"Sources":"Popular").isSelected(),"Refresh keeps the selected "+(sources?"Sources":"Popular")+" tab"));test.getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);test.waitForIdleSync();}finally{FeedStore.remove(a,fixture);}}
 static void run(Instrumentation test)throws Exception{
  Context c=test.getTargetContext();FeedStore.Feed first=new FeedStore.Feed(),second=new FeedStore.Feed();first.kind=second.kind="News";first.title="Source one";second.title="Source two";first.url="https://example.invalid/one";second.url="https://example.invalid/two";
  for(int n=0;n<3;n++){FeedStore.Item item=new FeedStore.Item();item.id="tab-test-one-"+n;item.title=item.id;first.items.add(item);}FeedStore.Item other=new FeedStore.Item();other.id="tab-test-two";other.title=other.id;second.items.add(other);ArrayList<FeedStore.Feed> feeds=new ArrayList<>(Arrays.asList(first,second));
  ArrayList<FeedHighlights.Entry> ranked=FeedHighlights.ranked(c,"News",feeds);FeedPostChecks.check(ranked.size()==4,"Combined tab includes all added sources");FeedPostChecks.check(ranked.get(1).feed==second,"New subscriptions interleave instead of one source flooding the list");
  try{FeedHighlights.opened(c,other);ranked=FeedHighlights.ranked(c,"News",feeds);FeedPostChecks.check(ranked.get(0).item==other,"Most opened item ranks first");FeedStore.Feed combined=FeedHighlights.combined(c,"News",feeds);FeedPostChecks.check(combined.origins.get(other)==second,"Combined items retain original source identity");}finally{c.getSharedPreferences("feed_activity",0).edit().remove(other.id).commit();}
  MainActivity a=(MainActivity)test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{for(String kind:new String[]{"News","Journals","Podcasts"}){
   test.runOnMainSync(()->FeedScreens.show(a,kind));test.waitForIdleSync();test.runOnMainSync(()->{TextView popular=text(a.mainFrame,"Popular"),sources=text(a.mainFrame,"Sources");FeedPostChecks.check(popular!=null&&sources!=null,"Both tabs present for "+kind);FeedPostChecks.check(popular.isSelected()&&!sources.isSelected(),"Popular is first/default tab for "+kind);if(!kind.equals("Podcasts")){View refresh=described(a.bar,kind.equals("News")?"Refresh news":"Refresh articles");FeedPostChecks.check(refresh instanceof ImageButton&&refresh.hasOnClickListeners(),"Refresh icon available on Popular for "+kind);}sources.performClick();});test.waitForIdleSync();
   test.runOnMainSync(()->{FeedPostChecks.check(text(a.mainFrame,"Sources").isSelected(),"Sources tab can be selected for "+kind);if(!kind.equals("Podcasts")){View refresh=described(a.bar,kind.equals("News")?"Refresh news":"Refresh articles");FeedPostChecks.check(refresh instanceof ImageButton&&refresh.hasOnClickListeners(),"Refresh icon available on Sources for "+kind);FeedPostChecks.check(a.feedSources,"Selected Sources tab remembered for refresh");}FeedPostChecks.check(text(a.mainFrame,"Add RSS feed")!=null,"Source management remains available for "+kind);text(a.mainFrame,"Popular").performClick();});test.waitForIdleSync();test.runOnMainSync(()->FeedPostChecks.check(text(a.mainFrame,"Popular").isSelected(),"Can return to Popular for "+kind));
  }refreshReturns(test,a,true);refreshReturns(test,a,false);}finally{test.runOnMainSync(a::finish);}
 }
}
